create extension if not exists pgcrypto;
create type public.school as enum ('harvard','mit','harvard_mit');
create type public.verification_status as enum ('pending','approved','rejected');
create type public.meeting_status as enum ('draft','confirmed','cancelled_on_time','late_cancellation','attendance_pending','completed','no_show','attendance_disputed');
create type public.job_status as enum ('pending','processing','succeeded','failed','cancelled');

create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table public.registry_imports(id uuid primary key default gen_random_uuid(),file_name text not null,file_hash text not null unique,source text not null default 'csv',status public.job_status not null default 'pending',total_rows int not null default 0,accepted_rows int not null default 0,rejected_rows int not null default 0,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),completed_at timestamptz);
create table public.alumni_registry(id uuid primary key default gen_random_uuid(),full_name text not null,email text,normalized_email text,phone text,normalized_phone text,school public.school,graduation_year int check(graduation_year between 1900 and 2100),active boolean not null default true,notes text not null default '',source text not null default 'manual',import_id uuid references public.registry_imports(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deactivated_at timestamptz,check(email is not null or phone is not null));
create index registry_email_idx on public.alumni_registry(normalized_email) where active; create index registry_phone_idx on public.alumni_registry(normalized_phone) where active;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text not null default '',normalized_email text not null default '',phone text not null default '',normalized_phone text not null default '',calendar_email text not null default '',linkedin_url text,school public.school,graduation_year int,city text,only_new_people boolean not null default false,verification_status public.verification_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path=public as $$
begin
  insert into public.profiles(id,full_name,email,normalized_email,calendar_email,verification_status)
  values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),coalesce(new.email,''),lower(trim(coalesce(new.email,''))),coalesce(new.email,''),'pending')
  on conflict(id) do nothing;
  return new;
end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_auth_user();
create table public.verification_requests(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id) on delete cascade,registry_id uuid references public.alumni_registry(id),status public.verification_status not null default 'pending',match_basis text check(match_basis is null or match_basis in('email','phone','manual')),match_confidence numeric(4,3),notes text not null default '',decided_by uuid references auth.users(id),decided_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_log(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id text not null,before_data jsonb,after_data jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.known_contacts(owner_id uuid not null references public.profiles(id) on delete cascade,normalized_phone text not null check(normalized_phone~'^\+[1-9][0-9]{6,14}$'),created_at timestamptz not null default now(),primary key(owner_id,normalized_phone));
create table public.weekly_availabilities(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,week_code text not null check(week_code~'^\d{4}-W\d{2}$'),slot_id text not null,is_active boolean not null default true,created_at timestamptz not null default now(),unique(user_id,week_code,slot_id));
create table public.match_batches(id uuid primary key default gen_random_uuid(),week_code text not null,idempotency_key text not null unique,status text not null check(status in('draft','confirmed','superseded')),revision int not null default 1,generated_by uuid not null references auth.users(id),confirmed_by uuid references auth.users(id),generated_at timestamptz not null default now(),confirmed_at timestamptz,unique(week_code,revision));
create table public.meetings(id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.match_batches(id) on delete cascade,week_code text not null,user_a_id uuid not null references public.profiles(id),user_b_id uuid not null references public.profiles(id),slot_id text not null,status public.meeting_status not null default 'draft',score numeric not null default 0,score_explanation jsonb not null default '{}',last_resort boolean not null default false,calendar_event_id text unique,meet_link text,cancelled_by uuid references public.profiles(id),cancelled_at timestamptz,cancellation_exempt boolean not null default false,cancellation_exempt_reason text,prior_completed_meeting_id uuid references public.meetings(id),created_at timestamptz not null default now(),check(user_a_id<>user_b_id),check(cancelled_by is null or cancelled_by in(user_a_id,user_b_id)));
create unique index one_active_match_a on public.meetings(week_code,user_a_id) where status not in('draft'); create unique index one_active_match_b on public.meetings(week_code,user_b_id) where status not in('draft');
create table public.meeting_participants(meeting_id uuid not null references public.meetings(id) on delete cascade,week_code text not null,user_id uuid not null references public.profiles(id),primary key(meeting_id,user_id),unique(week_code,user_id));
create table public.attendance_reports(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id) on delete cascade,reporter_id uuid not null references public.profiles(id),response_version int not null default 1,meeting_occurred boolean,self_attended boolean,partner_attended boolean,comment text,submitted_at timestamptz not null default now(),unique(meeting_id,reporter_id,response_version));
create table public.reputation_incidents(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meetings(id),user_id uuid not null references public.profiles(id),kind text not null check(kind in('no_show_no_notice','late_cancellation')),status text not null check(status in('pending_review','confirmed','dismissed')),idempotency_key text not null unique,decided_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.second_chances(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),incident_id uuid not null unique references public.reputation_incidents(id),granted_by uuid not null references auth.users(id),reason text not null,granted_at timestamptz not null default now());
create table public.meeting_config(key text primary key,value jsonb not null,updated_at timestamptz not null default now()); create table public.blocked_dates(meeting_date date primary key,reason text); create table public.contact_preferences(user_id uuid primary key references public.profiles(id) on delete cascade,opted_out boolean not null default false,updated_at timestamptz not null default now());
create table public.outbox(id uuid primary key default gen_random_uuid(),kind text not null,payload jsonb not null,idempotency_key text not null unique,status public.job_status not null default 'pending',attempt_count int not null default 0,next_attempt_at timestamptz not null default now(),last_error text,created_at timestamptz not null default now(),processed_at timestamptz);

create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
alter table public.admin_users enable row level security; alter table public.registry_imports enable row level security; alter table public.alumni_registry enable row level security; alter table public.profiles enable row level security; alter table public.verification_requests enable row level security; alter table public.audit_log enable row level security; alter table public.known_contacts enable row level security; alter table public.weekly_availabilities enable row level security; alter table public.match_batches enable row level security; alter table public.meetings enable row level security; alter table public.meeting_participants enable row level security; alter table public.attendance_reports enable row level security; alter table public.reputation_incidents enable row level security; alter table public.second_chances enable row level security; alter table public.meeting_config enable row level security; alter table public.blocked_dates enable row level security; alter table public.contact_preferences enable row level security; alter table public.outbox enable row level security;
create policy "admins registry" on public.alumni_registry for all using(public.is_admin()) with check(public.is_admin()); create policy "admins imports" on public.registry_imports for all using(public.is_admin()) with check(public.is_admin()); create policy "own profile" on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy "own profile insert" on public.profiles for insert with check(id=auth.uid()); create policy "own profile update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid()); create policy "admin profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin()); create policy "own verification" on public.verification_requests for select using(user_id=auth.uid() or public.is_admin()); create policy "admin verification" on public.verification_requests for all using(public.is_admin()) with check(public.is_admin()); create policy "admin audit" on public.audit_log for select using(public.is_admin()); create policy "own contacts" on public.known_contacts for all using(owner_id=auth.uid()) with check(owner_id=auth.uid()); create policy "own availability" on public.weekly_availabilities for all using(user_id=auth.uid() or public.is_admin()) with check(user_id=auth.uid() or public.is_admin()); create policy "admin batches" on public.match_batches for all using(public.is_admin()) with check(public.is_admin()); create policy "participant meeting" on public.meetings for select using(auth.uid() in(user_a_id,user_b_id) or public.is_admin()); create policy "admin meeting" on public.meetings for all using(public.is_admin()) with check(public.is_admin()); create policy "participant rows" on public.meeting_participants for select using(user_id=auth.uid() or public.is_admin()); create policy "admin participant rows" on public.meeting_participants for all using(public.is_admin()) with check(public.is_admin()); create policy "own report" on public.attendance_reports for all using(reporter_id=auth.uid()) with check(reporter_id=auth.uid()); create policy "own incidents" on public.reputation_incidents for select using(user_id=auth.uid() or public.is_admin()); create policy "admin incidents" on public.reputation_incidents for all using(public.is_admin()) with check(public.is_admin()); create policy "admin chances" on public.second_chances for all using(public.is_admin()) with check(public.is_admin()); create policy "public config" on public.meeting_config for select using(true); create policy "admin config" on public.meeting_config for all using(public.is_admin()) with check(public.is_admin()); create policy "public blocked" on public.blocked_dates for select using(true); create policy "admin blocked" on public.blocked_dates for all using(public.is_admin()) with check(public.is_admin()); create policy "own optout" on public.contact_preferences for all using(user_id=auth.uid()) with check(user_id=auth.uid());
alter table public.profiles add column headline text not null default '', add column bio text not null default '', add column industry text not null default '', add column "current_role" text not null default '', add column interests text[] not null default '{}', add column can_help_with text[] not null default '{}', add column looking_for text[] not null default '{}', add column avatar_url text, add column profile_visibility jsonb not null default '{"email":false,"phone":false,"linkedin":true}';
comment on table public.alumni_registry is 'Padrón cambiante: desactivar, nunca borrar relaciones históricas.'; comment on table public.match_batches is 'Borradores semanales regenerables y confirmación idempotente.'; comment on table public.outbox is 'Efectos externos idempotentes para Calendar, Meet y WhatsApp.';





